using System;
using System.Collections.Generic;
using System.Linq;

public static class Vowels
{
    public static int Count(string text)
    {
        int n = 0;
        foreach (char c in text.ToLower()) if ("aeiou".Contains(c)) n++;
        return n;
    }
}

