using System;
using System.Collections.Generic;
using System.Linq;

public static class Goal
{
    public static int MonthsToGoal(int goal, int monthly)
    {
        if (monthly <= 0) return -1;
        int saved = 0, months = 0;
        while (saved < goal) { saved += monthly; months++; }
        return months;
    }
}
